     1	package com.tainted.authuser.service;
     2	
     3	import com.tainted.authuser.domain.UserAccount;
     4	import com.tainted.authuser.domain.UserAccountRepository;
     5	import com.tainted.authuser.error.InvalidTokenException;
     6	import com.tainted.authuser.error.UserNotFoundException;
     7	import com.tainted.authuser.id.IdGenerator;
     8	import com.tainted.authuser.social.ExternalIdentity;
     9	import com.tainted.authuser.social.SocialVerifier;
    10	import com.tainted.authuser.token.TokenService;
    11	import com.tainted.authuser.web.dto.*;
    12	import org.springframework.stereotype.Service;
    13	import org.springframework.transaction.annotation.Transactional;
    14	import java.time.Clock;
    15	import java.time.Instant;
    16	
    17	@Service
    18	public class AuthService {
    19	
    20	    public static final String DISPLAY_NAME = "익명";
    21	
    22	    private final UserAccountRepository repository;
    23	    private final SocialVerifier socialVerifier;
    24	    private final TokenService tokenService;
    25	    private final IdGenerator idGenerator;
    26	    private final Clock clock;
    27	
    28	    public AuthService(UserAccountRepository repository, SocialVerifier socialVerifier,
    29	                       TokenService tokenService, IdGenerator idGenerator, Clock clock) {
    30	        this.repository = repository;
    31	        this.socialVerifier = socialVerifier;
    32	        this.tokenService = tokenService;
    33	        this.idGenerator = idGenerator;
    34	        this.clock = clock;
    35	    }
    36	
    37	    @Transactional
    38	    public LoginResponse login(LoginRequest request) {
    39	        ExternalIdentity identity = socialVerifier.verify(request.provider(), request.providerToken());
    40	        UserAccount user = repository
    41	                .findBySocialProviderAndExternalId(identity.provider(), identity.externalId())
    42	                .orElseGet(() -> repository.save(new UserAccount(
    43	                        idGenerator.newId(), identity.provider(), identity.externalId(), Instant.now(clock))));
    44	        String token = tokenService.issue(user.getId());
    45	        return new LoginResponse(token, DISPLAY_NAME);
    46	    }
    47	
    48	    @Transactional
    49	    public LoginResponse guest() {
    50	        UserAccount user = repository.save(new UserAccount(
    51	                idGenerator.newId(), "guest", "guest:" + idGenerator.newId(), Instant.now(clock)));
    52	        String token = tokenService.issue(user.getId());
    53	        return new LoginResponse(token, DISPLAY_NAME);
    54	    }
    55	
    56	    @Transactional(readOnly = true)
    57	    public MeResponse me(String token) {
    58	        String userId = tokenService.resolveUserId(token)
    59	                .orElseThrow(() -> new InvalidTokenException("invalid or expired token"));
    60	        UserAccount user = repository.findById(userId)
    61	                .orElseThrow(() -> new UserNotFoundException("user not found: " + userId));
    62	        return new MeResponse(user.getId(), DISPLAY_NAME, user.getSocialProvider());
    63	    }
    64	
    65	    @Transactional(readOnly = true)
    66	    public VerifyResponse verify(String token) {
    67	        return tokenService.resolveUserId(token)
    68	                .flatMap(repository::findById)
    69	                .map(u -> new VerifyResponse(true, u.getId(), u.getSocialProvider()))
    70	                .orElse(new VerifyResponse(false, null, null));
    71	    }
    72	
    73	    @Transactional(readOnly = true)
    74	    public UserResponse getUser(String id) {
    75	        UserAccount user = repository.findById(id)
    76	                .orElseThrow(() -> new UserNotFoundException("user not found: " + id));
    77	        return new UserResponse(user.getId(), user.getSocialProvider(), user.getCreatedAt().toString());
    78	    }
    79	}
