     1	package com.tainted.authuser.error;
     2	
     3	import org.springframework.http.HttpStatus;
     4	import org.springframework.http.ProblemDetail;
     5	import org.springframework.web.bind.MethodArgumentNotValidException;
     6	import org.springframework.web.bind.annotation.ExceptionHandler;
     7	import org.springframework.web.bind.annotation.RestControllerAdvice;
     8	
     9	@RestControllerAdvice
    10	public class GlobalExceptionHandler {
    11	
    12	    @ExceptionHandler(InvalidTokenException.class)
    13	    public ProblemDetail handleInvalidToken(InvalidTokenException ex) {
    14	        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.UNAUTHORIZED);
    15	        pd.setTitle("Invalid token");
    16	        pd.setDetail(ex.getMessage());
    17	        return pd;
    18	    }
    19	
    20	    @ExceptionHandler(UserNotFoundException.class)
    21	    public ProblemDetail handleUserNotFound(UserNotFoundException ex) {
    22	        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.NOT_FOUND);
    23	        pd.setTitle("User not found");
    24	        pd.setDetail(ex.getMessage());
    25	        return pd;
    26	    }
    27	
    28	    @ExceptionHandler(MethodArgumentNotValidException.class)
    29	    public ProblemDetail handleValidation(MethodArgumentNotValidException ex) {
