{
  "endpoint": {
    "method": "POST",
    "path": "/api/v1/auth/login",
    "controller": "AuthController",
    "controllerFile": "src/main/java/com/tainted/authuser/web/AuthController.java",
    "handler": "login"
  },
  "className": "AuthLoginBlackBoxTest",
  "sqlSlug": "auth-login",
  "docLines": [
    "login(): LoginRequest{provider,providerToken} 둘 다 @NotBlank → blank 시 400.",
    "provider/providerToken은 extract-key-params가 record accessor(request.provider())를 추적하지",
    "못해 RED로 잡히지 않았으나, CompositeSocialVerifier가 provider로 switch 분기하고",
    "MockSocialVerifier가 providerToken 접두사('valid-<provider>-')를 검사하는 직접 소스 분석",
    "(Step 3-A) 근거로 RED로 수동 분류함 — provider·providerToken 모두 VTC 대상.",
    "테스트 서버는 기본값(social.*.mode=mock)으로 기동된다고 가정 — MockSocialVerifier가",
    "google/kakao/naver/toss 모두 처리하므로 외부 HTTP 연동이 발생하지 않는다(WireMock 불필요).",
    "provider가 unsupported/malformed면 InvalidTokenException → 401 (GlobalExceptionHandler)."
  ],
  "seedParams": [
    {"name": "SEED", "kind": "id", "prefix": "lg"}
  ],
  "auth": {"pattern": "none"},
  "fixtures": {
    "setup": [],
    "teardown": [
      {"table": "user_account", "where": {"external_id": {"expr": "CONCAT('google:', '${SEED}')"}}},
      {"table": "user_account", "where": {"external_id": {"expr": "CONCAT('kakao:', '${SEED}')"}}},
      {"table": "user_account", "where": {"external_id": {"expr": "CONCAT('naver:', '${SEED}')"}}}
    ],
    "preDelete": true
  },
  "stubs": [],
  "tests": [
    {
      "name": "NTC_login_google_newUser",
      "jsonBody": {"provider": "google", "providerToken": "valid-google-${SEED}"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "displayName", "equalTo": "익명"},
        {"path": "accessToken", "notNullValue": true}
      ],
      "dbAssertions": [
        {"query": "SELECT social_provider FROM user_account WHERE external_id = CONCAT('google:', ?)",
         "args": ["${SEED}"], "expectEquals": "google"}
      ]
    },
    {
      "name": "NTC_login_kakao_newUser",
      "jsonBody": {"provider": "kakao", "providerToken": "valid-kakao-${SEED}"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "displayName", "equalTo": "익명"},
        {"path": "accessToken", "notNullValue": true}
      ],
      "dbAssertions": [
        {"query": "SELECT social_provider FROM user_account WHERE external_id = CONCAT('kakao:', ?)",
         "args": ["${SEED}"], "expectEquals": "kakao"}
      ]
    },
    {
      "name": "NTC_login_naver_newUser",
      "jsonBody": {"provider": "naver", "providerToken": "valid-naver-${SEED}"},
      "expectStatus": 200,
      "expectBody": [
        {"path": "displayName", "equalTo": "익명"},
        {"path": "accessToken", "notNullValue": true}
      ],
      "dbAssertions": [
        {"query": "SELECT social_provider FROM user_account WHERE external_id = CONCAT('naver:', ?)",
         "args": ["${SEED}"], "expectEquals": "naver"}
      ]
    },
    {
      "name": "VTC_provider_NULL",
      "jsonBody": {"provider": null, "providerToken": "valid-google-${SEED}"},
      "expectStatus": 400,
      "expectBody": [{"path": "title", "equalTo": "Validation failed"}]
    },
    {
      "name": "VTC_provider_EMPTY",
      "jsonBody": {"provider": "", "providerToken": "valid-google-${SEED}"},
      "expectStatus": 400,
      "expectBody": [{"path": "title", "equalTo": "Validation failed"}]
    },
    {
      "name": "VTC_provider_WHITE_SPACE",
      "jsonBody": {"provider": "   ", "providerToken": "valid-google-${SEED}"},
      "expectStatus": 400,
      "expectBody": [{"path": "title", "equalTo": "Validation failed"}]
    },
    {
      "name": "VTC_providerToken_NULL",
      "jsonBody": {"provider": "google", "providerToken": null},
      "expectStatus": 400,
      "expectBody": [{"path": "title", "equalTo": "Validation failed"}]
    },
    {
      "name": "VTC_providerToken_EMPTY",
      "jsonBody": {"provider": "google", "providerToken": ""},
      "expectStatus": 400,
      "expectBody": [{"path": "title", "equalTo": "Validation failed"}]
    },
    {
      "name": "ATC_login_unsupportedProvider",
      "jsonBody": {"provider": "facebook", "providerToken": "valid-facebook-${SEED}"},
      "expectStatus": 401,
      "expectBody": [
        {"path": "title", "equalTo": "Invalid token"},
        {"path": "detail", "equalTo": "unsupported provider: facebook"}
      ]
    },
    {
      "name": "ATC_login_malformedProviderToken",
      "jsonBody": {"provider": "google", "providerToken": "not-the-right-format"},
      "expectStatus": 401,
      "expectBody": [
        {"path": "title", "equalTo": "Invalid token"},
        {"path": "detail", "equalTo": "malformed token for provider: google"}
      ]
    }
  ]
}

